from itertools import combinations

# works: 0-2 French novels, 3-5 Russian novels, 6-7 French plays, 8 Russian play
FN = {0, 1, 2}; RN = {3, 4, 5}; FP = {6, 7}; RP = {8}

def valid(s):
    fn = len(s & FN); rn = len(s & RN); fp = len(s & FP); rp = len(s & RP)
    if not 5 <= len(s) <= 6: return False
    if fn + fp > 4: return False
    if not 3 <= fn + rn <= 4: return False
    if fn < rn: return False
    if fp == 2 and rp == 1: return False
    return True

def counts(s):
    return (len(s & FN), len(s & RN), len(s & FP), len(s & RP))

opts = {
    'A': lambda fn, rn, fp, rp: rn == 0 and fp + rp == 1,
    'B': lambda fn, rn, fp, rp: rn == 1 and fp == 2,
    'C': lambda fn, rn, fp, rp: fn == 2 and rp == 1,
    'D': lambda fn, rn, fp, rp: fn == 2 and fp + rp == 2,
    'E': lambda fn, rn, fp, rp: rn == 2 and fp + rp == 1,
}

sols = [set(c) for k in (5, 6) for c in combinations(range(9), k) if valid(set(c))]
print("valid selections:", len(sols))

possible = {}
for k, f in opts.items():
    ex = next((sorted(s) for s in sols if f(*counts(set(s)))), None)
    possible[k] = ex
    print(k, "possible" if ex else "IMPOSSIBLE", ex)

impossible = [k for k, v in possible.items() if v is None]
print("Options that cannot be true:", impossible)
claimed = 'A'
if impossible == [claimed]:
    print("CHECK PASS")
else:
    print("CHECK FAIL: expected", impossible, "claimed", claimed)
